package com.android.messaging.ui.conversationlist;
import android.view.LayoutInflater;import android.view.ViewGroup;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.android.messaging.R;import com.android.messaging.sms.SmsRepository;import java.util.ArrayList;import java.util.List;import java.util.Locale;
public final class ConversationListAdapter extends RecyclerView.Adapter<ConversationListAdapter.H>{public interface Host{void open(SmsRepository.Conversation c);void menu(SmsRepository.Conversation c);}private final Host host;private final ArrayList<SmsRepository.Conversation>all=new ArrayList<>(),shown=new ArrayList<>();private String filter="";public ConversationListAdapter(Host h){host=h;}public void setItems(List<SmsRepository.Conversation>x){all.clear();if(x!=null)all.addAll(x);apply();}public void filter(String s){filter=s==null?"":s.trim().toLowerCase(Locale.US);apply();}private void apply(){shown.clear();for(SmsRepository.Conversation c:all)if(filter.isEmpty()||has(c.title)||has(c.address)||has(c.snippet))shown.add(c);notifyDataSetChanged();}private boolean has(String s){return s!=null&&s.toLowerCase(Locale.US).contains(filter);}@NonNull @Override public H onCreateViewHolder(@NonNull ViewGroup p,int t){ConversationListItemView v=(ConversationListItemView)LayoutInflater.from(p.getContext()).inflate(R.layout.conversation_list_item_view,p,false);return new H(v);}@Override public void onBindViewHolder(@NonNull H h,int p){SmsRepository.Conversation c=shown.get(p);h.v.bind(c);h.v.setOnClickListener(x->host.open(c));h.v.setOnLongClickListener(x->{host.menu(c);return true;});}@Override public int getItemCount(){return shown.size();}public SmsRepository.Conversation get(int p){return shown.get(p);}static final class H extends RecyclerView.ViewHolder{final ConversationListItemView v;H(ConversationListItemView v){super(v);this.v=v;}}}
